import { useState, useEffect } from "react";
import { Modal, Button, Input, Table, message, Alert, Spin, Tag, Card, Select, InputNumber } from "antd";
import { DeleteOutlined } from "@ant-design/icons";
import axios from "axios";
import {
  getSurroundingAIQuestions,
  generateSurroundingAI,
  updateSurrounding,
} from "@/services/enterpriseService";
import type { SurroundingInfo, NearbyUnit, SensitiveTarget } from "@/types/enterprise";
import { omitFields } from "@/utils/omitFields";

interface Props {
  enterpriseId: string;
  existingSurrounding: SurroundingInfo;
  visible: boolean;
  onClose: () => void;
  onImported: () => void;
}

type Step = "loading-questions" | "answer" | "generating" | "preview";

interface AIQuestion {
  id: string;
  question: string;
}

interface EditableNearby extends NearbyUnit {
  _key: string;
  _isNew: boolean;
}

interface EditableTarget extends SensitiveTarget {
  _key: string;
  _isNew: boolean;
}

const DIRECTIONS = ["N", "NE", "E", "SE", "S", "SW", "W", "NW"];

/** 解析请求错误：优先透出后端 detail（如 504「AI 响应超时」），其次 e.message，最后兜底文案 */
function errorDetail(e: unknown, fallback: string): string {
  if (axios.isAxiosError(e) && e.response?.data?.detail) {
    return e.response.data.detail;
  }
  return e instanceof Error && e.message ? e.message : fallback;
}

export default function SurroundingAIGenerateModal({
  enterpriseId,
  existingSurrounding,
  visible,
  onClose,
  onImported,
}: Props) {
  const [step, setStep] = useState<Step>("loading-questions");
  const [questions, setQuestions] = useState<AIQuestion[]>([]);
  const [answers, setAnswers] = useState<Record<string, string>>({});
  const [customSupplement, setCustomSupplement] = useState("");
  const [saving, setSaving] = useState(false);

  // Preview state - merged existing + generated
  const [nearbyUnits, setNearbyUnits] = useState<EditableNearby[]>([]);
  const [sensitiveTargets, setSensitiveTargets] = useState<EditableTarget[]>([]);
  const [trafficInfo, setTrafficInfo] = useState("");

  useEffect(() => {
    if (visible) {
      loadQuestions();
    }
  }, [visible, enterpriseId]);

  const loadQuestions = async () => {
    setStep("loading-questions");
    try {
      // 页面 catch 自带 toast，跳过全局统一 toast 避免双弹（F4 skip 机制）
      const qs = await getSurroundingAIQuestions(enterpriseId, { skipGlobalError: true });
      if (qs.length === 0) {
        message.error("未能生成调查问题，请重试");
        onClose();
        return;
      }
      setQuestions(qs);
      setAnswers({});
      setCustomSupplement("");
      setStep("answer");
    } catch {
      message.error("AI 服务暂不可用，请检查 AI 配置");
      onClose();
    }
  };

  const handleGenerate = async () => {
    setStep("generating");
    try {
      const answerList = questions.map((q) => ({
        question_id: q.id,
        question: q.question,
        answer: answers[q.id] || "",
      }));
      if (customSupplement.trim()) {
        answerList.push({
          question_id: "custom",
          question: "补充描述",
          answer: customSupplement.trim(),
        });
      }
      // 页面 catch 自带 toast，跳过全局统一 toast 避免双弹（F4 skip 机制）
      const generated = await generateSurroundingAI(enterpriseId, answerList, { skipGlobalError: true });

      // Merge existing + generated with _key and _isNew markers
      const existingUnits: EditableNearby[] = (existingSurrounding.nearby_units || []).map(
        (u, i) => ({ ...u, _key: `existing-unit-${i}`, _isNew: false }),
      );
      const generatedUnits: EditableNearby[] = generated.nearby_units.map((u, i) => ({
        ...u,
        _key: `generated-unit-${i}`,
        _isNew: true,
      }));

      const existingTargets: EditableTarget[] = (existingSurrounding.sensitive_targets || []).map(
        (t, i) => ({ ...t, _key: `existing-target-${i}`, _isNew: false }),
      );
      const generatedTargets: EditableTarget[] = generated.sensitive_targets.map((t, i) => ({
        ...t,
        _key: `generated-target-${i}`,
        _isNew: true,
      }));

      setNearbyUnits([...existingUnits, ...generatedUnits]);
      setSensitiveTargets([...existingTargets, ...generatedTargets]);
      setTrafficInfo(generated.traffic_info || existingSurrounding.traffic_info || "");
      setStep("preview");
    } catch (e) {
      message.error(errorDetail(e, "AI 生成失败，请重试"));
      setStep("answer");
    }
  };

  const handleSave = async () => {
    setSaving(true);
    try {
      const toSave: SurroundingInfo = {
        nearby_units: nearbyUnits.map((unit) => omitFields(unit, ["_key", "_isNew"] as const)),
        sensitive_targets: sensitiveTargets.map((target) => omitFields(target, ["_key", "_isNew"] as const)),
        traffic_info: trafficInfo,
      };
      // 页面 catch 自带 toast，跳过全局统一 toast 避免双弹（F4 skip 机制）
      await updateSurrounding(enterpriseId, toSave, { skipGlobalError: true });
      message.success("周边环境已更新");
      onImported();
      resetAll();
    } catch {
      message.error("保存失败");
    } finally {
      setSaving(false);
    }
  };

  const resetAll = () => {
    setStep("loading-questions");
    setQuestions([]);
    setAnswers({});
    setCustomSupplement("");
    setNearbyUnits([]);
    setSensitiveTargets([]);
    setTrafficInfo("");
    onClose();
  };

  // --- Nearby units editing helpers ---
  const updateNearby = (key: string, field: string, value: unknown) => {
    setNearbyUnits((prev) =>
      prev.map((u) => (u._key === key ? { ...u, [field]: value } : u)),
    );
  };

  const deleteNearby = (key: string) => {
    setNearbyUnits((prev) => prev.filter((u) => u._key !== key));
  };

  // --- Sensitive targets editing helpers ---
  const updateTarget = (key: string, field: string, value: unknown) => {
    setSensitiveTargets((prev) =>
      prev.map((t) => (t._key === key ? { ...t, [field]: value } : t)),
    );
  };

  const deleteTarget = (key: string) => {
    setSensitiveTargets((prev) => prev.filter((t) => t._key !== key));
  };

  return (
    <Modal
      title="AI 智能生成周边环境"
      open={visible}
      onCancel={resetAll}
      width={960}
      footer={
        step === "preview"
          ? [
              <Button key="back" onClick={resetAll}>
                取消
              </Button>,
              <Button key="save" type="primary" loading={saving} onClick={handleSave}>
                确认保存（{nearbyUnits.length} 个周边单位，{sensitiveTargets.length} 个敏感目标）
              </Button>,
            ]
          : step === "answer"
            ? [
                <Button key="cancel" onClick={resetAll}>
                  取消
                </Button>,
                <Button key="generate" type="primary" onClick={handleGenerate}>
                  生成周边环境
                </Button>,
              ]
            : null
      }
    >
      {step === "loading-questions" && (
        <div style={{ textAlign: "center", padding: 40 }}>
          <Spin size="large" />
          <p style={{ marginTop: 16 }}>AI 正在分析企业档案，生成周边环境调查问题...</p>
        </div>
      )}

      {step === "answer" && (
        <div>
          <Alert
            type="info"
            message="请回答以下问题，帮助 AI 全面了解该企业的周边环境"
            style={{ marginBottom: 16 }}
            showIcon
          />
          <div style={{ display: "flex", flexDirection: "column", gap: 16, maxHeight: "50vh", overflow: "auto" }}>
            {questions.map((q) => (
              <div key={q.id}>
                <div style={{ fontWeight: 500, marginBottom: 4 }}>{q.question}</div>
                <Input.TextArea
                  value={answers[q.id] || ""}
                  onChange={(e) =>
                    setAnswers((prev) => ({ ...prev, [q.id]: e.target.value }))
                  }
                  placeholder="请输入您的回答..."
                  rows={2}
                />
              </div>
            ))}
          </div>

          <div style={{ marginTop: 20 }}>
            <div style={{ fontWeight: 500, marginBottom: 6, color: "#595959" }}>
              自行补充描述（选填）
            </div>
            <div style={{ fontSize: 12, color: "#999", marginBottom: 8 }}>
              如果 AI 生成的问题未覆盖您想补充的信息，可在此输入补充描述。
            </div>
            <Input.TextArea
              value={customSupplement}
              onChange={(e) => setCustomSupplement(e.target.value)}
              placeholder="例如：厂区北侧有一条季节性河流，雨季需关注防汛..."
              rows={3}
            />
          </div>
        </div>
      )}

      {step === "generating" && (
        <div style={{ textAlign: "center", padding: 40 }}>
          <Spin size="large" />
          <p style={{ marginTop: 16 }}>AI 生成中，通常需要 1-2 分钟，请耐心等待…</p>
        </div>
      )}

      {step === "preview" && (
        <div>
          <Alert
            type="success"
            message="AI 已生成周边环境信息，可编辑或删除后确认保存。蓝色标记项为新增数据。"
            style={{ marginBottom: 12 }}
            showIcon
          />

          {/* Nearby Units */}
          <Card title="周边单位" size="small" style={{ marginBottom: 12 }}>
            <Table
              dataSource={nearbyUnits}
              rowKey="_key"
              pagination={false}
              size="small"
              scroll={{ y: 240 }}
              columns={[
                {
                  title: "名称",
                  dataIndex: "name",
                  width: 180,
                  render: (v: string, record: EditableNearby) => (
                    <Input
                      size="small"
                      value={v}
                      onChange={(e) => updateNearby(record._key, "name", e.target.value)}
                      prefix={record._isNew ? <Tag color="blue" style={{ marginRight: 4 }}>新</Tag> : undefined}
                    />
                  ),
                },
                {
                  title: "方位",
                  dataIndex: "direction",
                  width: 100,
                  render: (v: string, record: EditableNearby) => (
                    <Select
                      size="small"
                      value={v}
                      onChange={(val) => updateNearby(record._key, "direction", val)}
                      options={DIRECTIONS.map((d) => ({ value: d, label: d }))}
                      style={{ width: "100%" }}
                    />
                  ),
                },
                {
                  title: "距离(m)",
                  dataIndex: "distance_m",
                  width: 100,
                  render: (v: number, record: EditableNearby) => (
                    <InputNumber
                      size="small"
                      value={v}
                      onChange={(val) => updateNearby(record._key, "distance_m", val || 0)}
                      style={{ width: "100%" }}
                    />
                  ),
                },
                {
                  title: "主要风险",
                  dataIndex: "main_risk",
                  render: (v: string, record: EditableNearby) => (
                    <Input
                      size="small"
                      value={v}
                      onChange={(e) => updateNearby(record._key, "main_risk", e.target.value)}
                    />
                  ),
                },
                {
                  title: "标记",
                  width: 70,
                  render: (_: unknown, record: EditableNearby) =>
                    record._isNew ? <Tag color="blue">新增</Tag> : <Tag>已有</Tag>,
                },
                {
                  title: "",
                  width: 40,
                  render: (_: unknown, record: EditableNearby) => (
                    <Button
                      type="text"
                      size="small"
                      danger
                      icon={<DeleteOutlined />}
                      onClick={() => deleteNearby(record._key)}
                    />
                  ),
                },
              ]}
            />
          </Card>

          {/* Sensitive Targets */}
          <Card title="敏感目标" size="small" style={{ marginBottom: 12 }}>
            <Table
              dataSource={sensitiveTargets}
              rowKey="_key"
              pagination={false}
              size="small"
              scroll={{ y: 240 }}
              columns={[
                {
                  title: "名称",
                  dataIndex: "name",
                  width: 180,
                  render: (v: string, record: EditableTarget) => (
                    <Input
                      size="small"
                      value={v}
                      onChange={(e) => updateTarget(record._key, "name", e.target.value)}
                      prefix={record._isNew ? <Tag color="blue" style={{ marginRight: 4 }}>新</Tag> : undefined}
                    />
                  ),
                },
                {
                  title: "方位",
                  dataIndex: "direction",
                  width: 100,
                  render: (v: string, record: EditableTarget) => (
                    <Select
                      size="small"
                      value={v}
                      onChange={(val) => updateTarget(record._key, "direction", val)}
                      options={DIRECTIONS.map((d) => ({ value: d, label: d }))}
                      style={{ width: "100%" }}
                    />
                  ),
                },
                {
                  title: "距离(m)",
                  dataIndex: "distance_m",
                  width: 100,
                  render: (v: number, record: EditableTarget) => (
                    <InputNumber
                      size="small"
                      value={v}
                      onChange={(val) => updateTarget(record._key, "distance_m", val || 0)}
                      style={{ width: "100%" }}
                    />
                  ),
                },
                {
                  title: "类型",
                  dataIndex: "type",
                  render: (v: string, record: EditableTarget) => (
                    <Input
                      size="small"
                      value={v}
                      onChange={(e) => updateTarget(record._key, "type", e.target.value)}
                    />
                  ),
                },
                {
                  title: "标记",
                  width: 70,
                  render: (_: unknown, record: EditableTarget) =>
                    record._isNew ? <Tag color="blue">新增</Tag> : <Tag>已有</Tag>,
                },
                {
                  title: "",
                  width: 40,
                  render: (_: unknown, record: EditableTarget) => (
                    <Button
                      type="text"
                      size="small"
                      danger
                      icon={<DeleteOutlined />}
                      onClick={() => deleteTarget(record._key)}
                    />
                  ),
                },
              ]}
            />
          </Card>

          {/* Traffic Info */}
          <Card title="交通状况" size="small">
            <Input.TextArea
              value={trafficInfo}
              onChange={(e) => setTrafficInfo(e.target.value)}
              rows={3}
            />
          </Card>
        </div>
      )}
    </Modal>
  );
}

import { useState } from "react";
import { Alert, Button, Checkbox, Collapse, Input, List, Modal, Space, Spin, Tag, Upload, message } from "antd";
import { InboxOutlined } from "@ant-design/icons";
import {
  analyzeFourColorMap,
  cancelFourColorImport,
  commitFourColorImport,
} from "@/services/riskMappingWorkbenchService";
import type {
  FourColorAnalyzeResult,
  FourColorCommitResult,
  FourColorDraftZone,
  FourColorExcludedItem,
  FourColorTextItem,
} from "@/types/riskMappingWorkbench";
import type { RiskLevel } from "@/types/riskManagement";

interface FourColorImportModalProps {
  open: boolean;
  enterpriseId: string;
  floorId: string;
  hasExistingData: boolean;
  existingZoneCount: number;
  existingRiskPointCount: number;
  onClose: () => void;
  onImported: (result: FourColorCommitResult) => void;
}

type Stage = "select" | "analyzing" | "preview";

const LEVEL_COLORS: Record<string, string> = {
  重大: "#ff4d4f",
  较大: "#fa8c16",
  一般: "#fadb14",
  低: "#52c41a",
};

const COLOR_LEVEL: Record<string, RiskLevel> = { 红: "重大", 橙: "较大", 黄: "一般", 蓝: "低" };
const REASON_LABEL: Record<string, string> = {
  legend: "图例",
  thin: "细长线/符号",
  border_frame: "贴边图框",
  tiny: "极小噪点",
};

function extractToken(previewUrl: string): string {
  return previewUrl.split("/four_color_tmp/")[1]?.split("/")[0] ?? "";
}

export default function FourColorImportModal({
  open,
  enterpriseId,
  floorId,
  hasExistingData,
  existingZoneCount,
  existingRiskPointCount,
  onClose,
  onImported,
}: FourColorImportModalProps) {
  const [stage, setStage] = useState<Stage>("select");
  const [result, setResult] = useState<FourColorAnalyzeResult | null>(null);
  const [zones, setZones] = useState<FourColorDraftZone[]>([]);
  const [replaceExisting, setReplaceExisting] = useState(true);
  const [submitting, setSubmitting] = useState(false);
  const [excluded, setExcluded] = useState<FourColorExcludedItem[]>([]);
  const [texts, setTexts] = useState<FourColorTextItem[]>([]);
  const [showTexts, setShowTexts] = useState(true);
  const [selectedZoneId, setSelectedZoneId] = useState<string | null>(null);
  const [search, setSearch] = useState("");
  const [activeLevel, setActiveLevel] = useState<string | null>(null);
  const [editingName, setEditingName] = useState("");
  const [popover, setPopover] = useState<{ zoneId: string; x: number; y: number } | null>(null);

  const reset = () => {
    setStage("select");
    setResult(null);
    setZones([]);
    setReplaceExisting(true);
    setExcluded([]);
    setTexts([]);
    setShowTexts(true);
    setSelectedZoneId(null);
    setSearch("");
    setActiveLevel(null);
    setEditingName("");
    setPopover(null);
  };

  const handleClose = () => {
    const token = result ? extractToken(result.preview_url) : "";
    if (token) {
      cancelFourColorImport(enterpriseId, floorId, token).catch(() => undefined);
    }
    reset();
    onClose();
  };

  const runAnalyze = async (file: File) => {
    setStage("analyzing");
    try {
      const res = await analyzeFourColorMap(enterpriseId, floorId, file);
      setResult(res);
      setZones(res.zones.map(z => ({ ...z, name: z.suggested_name || z.name })));
      setExcluded(res.excluded);
      setTexts(res.texts);
      setStage("preview");
    } catch (e) {
      const err = e as { response?: { data?: { detail?: { code?: string; message?: string } } } };
      const detail = err?.response?.data?.detail;
      const msg = typeof detail === "string" ? detail : detail?.message;
      if (detail && typeof detail !== "string" && detail.code === "NO_ZONE_DETECTED") {
        message.error(msg || "未识别到红/橙/黄/蓝色块，请检查图片");
      } else {
        message.error(msg || "识别失败，请重试");
      }
      setStage("select");
    }
  };

  const handleCommit = async () => {
    if (!result || zones.length === 0) return;
    setSubmitting(true);
    try {
      const payload = {
        file_token: extractToken(result.preview_url),
        zones: zones.map(z => ({
          name: z.name,
          risk_level: z.risk_level,
          polygons: z.polygons.map(p => ({ points: p.points })),
        })),
        replace_existing: replaceExisting,
      };
      const commitResult = await commitFourColorImport(enterpriseId, floorId, payload);
      onImported(commitResult);
      reset();
    } catch (e) {
      const err = e as { response?: { data?: { detail?: { code?: string; message?: string } } } };
      const detail = err?.response?.data?.detail;
      message.error(typeof detail === "string" ? detail : detail?.message || "落图失败，请重试");
    } finally {
      setSubmitting(false);
    }
  };

  const handleRestore = (item: FourColorExcludedItem) => {
    const level = COLOR_LEVEL[item.color] ?? "一般";
    const newZone: FourColorDraftZone = {
      client_id: `draft-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`,
      name: `分区${zones.length + 1}`,
      risk_level: level,
      color: LEVEL_COLORS[level],
      polygons: item.polygons,
    };
    setZones([...zones, newZone]);
    setExcluded(excluded.filter(x => x !== item));
  };

  const updateZoneName = (id: string, name: string) => {
    setZones(zones.map(z => (z.client_id === id ? { ...z, name } : z)));
  };

  const deleteZone = (id: string) => {
    setZones(zones.filter(z => z.client_id !== id));
    if (selectedZoneId === id) {
      setSelectedZoneId(null);
      setPopover(null);
    }
  };

  const openPopover = (z: FourColorDraftZone, x: number, y: number) => {
    setSelectedZoneId(z.client_id);
    setEditingName(z.name);
    setPopover({ zoneId: z.client_id, x, y });
  };

  const selectZoneByRow = (z: FourColorDraftZone) => {
    const pts = z.polygons[0]?.points ?? [];
    const xs = pts.map(p => p.x);
    const ys = pts.map(p => p.y);
    const cx = xs.length ? (Math.min(...xs) + Math.max(...xs)) / 2 : 50;
    const cy = ys.length ? (Math.min(...ys) + Math.max(...ys)) / 2 : 50;
    openPopover(z, cx, cy);
  };

  const savePopoverName = () => {
    if (!popover) return;
    updateZoneName(popover.zoneId, editingName.trim() || zones.find(z => z.client_id === popover.zoneId)?.name || "");
    setSelectedZoneId(null);
    setPopover(null);
  };

  const bulkDelete = () => {
    if (!activeLevel) return;
    const n = zones.filter(z => z.risk_level === activeLevel).length;
    setZones(zones.filter(z => z.risk_level !== activeLevel));
    setSelectedZoneId(null);
    setPopover(null);
    message.success(`已批量删除 ${n} 个「${activeLevel}」分区`);
  };

  const filteredZones = zones.filter(z =>
    (!activeLevel || z.risk_level === activeLevel) &&
    (!search || z.name.includes(search)),
  );
  const levelGroups = (["重大", "较大", "一般", "低"] as const)
    .map(level => ({ level, items: filteredZones.filter(z => z.risk_level === level) }))
    .filter(g => g.items.length > 0);

  return (
    <Modal
      open={open}
      title="导入四色分布图"
      width={860}
      onCancel={handleClose}
      destroyOnHidden
      footer={[
        <Button key="cancel" onClick={handleClose}>取消</Button>,
        <Button
          key="commit"
          type="primary"
          disabled={stage !== "preview" || zones.length === 0 || submitting}
          loading={submitting}
          onClick={handleCommit}
        >
          确认落图
        </Button>,
      ]}
    >
      {stage === "select" && (
        <Upload.Dragger
          accept="image/png,image/jpeg,image/webp"
          showUploadList={false}
          beforeUpload={file => {
            runAnalyze(file as unknown as File);
            return false;
          }}
        >
          <p className="ant-upload-drag-icon"><InboxOutlined /></p>
          <p className="ant-upload-text">点击或拖拽上传四色分布图（PNG/JPEG/WebP，≤20MB）</p>
        </Upload.Dragger>
      )}
      {stage === "analyzing" && (
        <div style={{ textAlign: "center", padding: 48 }}>
          <Spin tip="正在识别四色区域…">
            <div style={{ width: 80, height: 80 }} />
          </Spin>
        </div>
      )}
      {stage === "preview" && result && (
        <div>
          {result.warnings.map(w => (
            <Alert key={w} type="warning" showIcon message={w} style={{ marginBottom: 8 }} />
          ))}
          <div style={{ display: "grid", gridTemplateColumns: "1fr 280px", gap: 12, minHeight: 320 }}>
            <div
              style={{
                position: "relative",
                background: "#fafafa",
                borderRadius: 8,
                overflow: "hidden",
                alignSelf: "start",
                aspectRatio: `${result.canvas_width} / ${result.canvas_height}`,
                width: "100%",
              }}
            >
              <img
                src={result.preview_url}
                alt="四色分布图预览"
                style={{
                  position: "absolute",
                  inset: 0,
                  width: "100%",
                  height: "100%",
                  objectFit: "fill",
                }}
              />
              <svg
                viewBox="0 0 100 100"
                preserveAspectRatio="none"
                style={{ position: "absolute", inset: 0, width: "100%", height: "100%" }}
              >
                {zones.map(z =>
                  z.polygons.map(p => (
                    <polygon
                      key={p.id}
                      points={p.points.map(pt => `${pt.x},${pt.y}`).join(" ")}
                      fill={LEVEL_COLORS[z.risk_level]}
                      fillOpacity={selectedZoneId === z.client_id ? 0.6 : 0.35}
                      stroke={LEVEL_COLORS[z.risk_level]}
                      strokeWidth={selectedZoneId === z.client_id ? 2 : 1}
                      vectorEffect="non-scaling-stroke"
                      style={{ cursor: "pointer" }}
                      onClick={e => {
                        const svg = e.currentTarget.ownerSVGElement;
                        const box = svg?.getBoundingClientRect();
                        const x = box ? ((e.nativeEvent.clientX - box.left) / box.width) * 100 : 50;
                        const y = box ? ((e.nativeEvent.clientY - box.top) / box.height) * 100 : 50;
                        openPopover(z, Math.min(100, Math.max(0, x)), Math.min(100, Math.max(0, y)));
                      }}
                    />
                  )),
                )}
              </svg>
              {popover && (
                <div
                  style={{
                    position: "absolute",
                    left: `max(4px, min(calc(${popover.x}% - 95px), calc(100% - 200px)))`,
                    top: `max(4px, min(calc(${popover.y}% - 88px), calc(100% - 84px)))`,
                    background: "#fff",
                    border: "1px solid #d9d9d9",
                    borderRadius: 8,
                    boxShadow: "0 4px 16px rgba(0,0,0,.12)",
                    padding: 8,
                    zIndex: 5,
                    width: 190,
                  }}
                >
                  <Input
                    value={editingName}
                    onChange={e => setEditingName(e.target.value)}
                    onKeyDown={e => { if (e.key === "Enter") savePopoverName(); }}
                    aria-label="预览改名"
                    size="small"
                    autoFocus
                    style={{ marginBottom: 6 }}
                  />
                  <Space size={4}>
                    <Button size="small" type="primary" onClick={savePopoverName}>保存</Button>
                    <Button size="small" danger onClick={() => deleteZone(popover.zoneId)}>删除</Button>
                    <Button
                      size="small"
                      type="text"
                      onClick={() => { setSelectedZoneId(null); setPopover(null); }}
                    >
                      关闭
                    </Button>
                  </Space>
                </div>
              )}
              {texts.length > 0 && (
                <Checkbox
                  checked={showTexts}
                  onChange={e => setShowTexts(e.target.checked)}
                  style={{ position: "absolute", top: 8, right: 8, zIndex: 2, background: "rgba(255,255,255,.85)", padding: "0 6px" }}
                >
                  文字标注
                </Checkbox>
              )}
              {showTexts && texts.map((t, i) => (
                <svg key={`text-${i}`} viewBox="0 0 100 100" preserveAspectRatio="none" style={{ position: "absolute", inset: 0, width: "100%", height: "100%", pointerEvents: "none" }}>
                  <polygon
                    points={t.points.map(p => `${p.x},${p.y}`).join(" ")}
                    fill="none"
                    stroke="#1677ff"
                    strokeWidth={1}
                    strokeDasharray="3 3"
                    vectorEffect="non-scaling-stroke"
                  />
                </svg>
              ))}
            </div>
            <div>
              <div style={{ display: "flex", flexDirection: "column", gap: 8 }}>
                <Input
                  placeholder="搜索分区名"
                  value={search}
                  allowClear
                  onChange={e => setSearch(e.target.value)}
                />
                <Space wrap size={4}>
                  {(["重大", "较大", "一般", "低"] as const).map(level => (
                    <Button
                      key={level}
                      data-testid={`filter-${level}`}
                      size="small"
                      onClick={() => setActiveLevel(activeLevel === level ? null : level)}
                      style={
                        activeLevel === level
                          ? { background: LEVEL_COLORS[level], borderColor: LEVEL_COLORS[level], color: level === "一般" ? "#333" : "#fff" }
                          : undefined
                      }
                    >
                      {level} {zones.filter(z => z.risk_level === level).length}
                    </Button>
                  ))}
                  <Button size="small" danger disabled={!activeLevel} onClick={bulkDelete}>批量删除</Button>
                </Space>
                <div style={{ maxHeight: 420, overflowY: "auto", margin: "0 -8px", padding: "0 8px" }}>
                  <Collapse
                    ghost
                    defaultActiveKey={levelGroups.map(g => g.level)}
                    items={levelGroups.map(g => ({
                      key: g.level,
                      label: (
                        <Space size={6}>
                          <Tag color={LEVEL_COLORS[g.level]}>{g.level}</Tag>
                          <span style={{ color: "#999", fontSize: 12 }}>{g.items.length}</span>
                        </Space>
                      ),
                      children: (
                        <List
                          size="small"
                          dataSource={g.items}
                          renderItem={(z) => (
                            <List.Item
                              style={selectedZoneId === z.client_id ? { background: "#e6f4ff", borderRadius: 6 } : undefined}
                              onClick={() => selectZoneByRow(z)}
                              actions={[
                                <Button
                                  key="del"
                                  type="text"
                                  danger
                                  size="small"
                                  onClick={e => { e.stopPropagation(); deleteZone(z.client_id); }}
                                >
                                  删除
                                </Button>,
                              ]}
                            >
                              <div style={{ width: "100%" }}>
                                <Input
                                  value={z.name}
                                  aria-label={`分区名称${zones.indexOf(z) + 1}`}
                                  size="small"
                                  onClick={e => e.stopPropagation()}
                                  onChange={e => updateZoneName(z.client_id, e.target.value)}
                                  style={{ marginBottom: 4 }}
                                />
                                <Tag color={LEVEL_COLORS[z.risk_level]}>{z.risk_level}</Tag>
                                {z.suspected && (
                                  <Tag color="orange" title={z.ai_hint || "形状异常，可能不是真实分区"}>疑似干扰</Tag>
                                )}
                              </div>
                            </List.Item>
                          )}
                        />
                      ),
                    }))}
                  />
                  {filteredZones.length === 0 && (
                    <div style={{ textAlign: "center", color: "#999", padding: "24px 0", fontSize: 13 }}>
                      没有匹配的分区
                    </div>
                  )}
                </div>
              </div>
              {excluded.length > 0 && (
                <Collapse
                  style={{ marginTop: 12 }}
                  items={[{
                    key: "excluded",
                    label: `已自动排除干扰项（${excluded.length}）`,
                    children: (
                      <List
                        size="small"
                        dataSource={excluded}
                        renderItem={(item, i) => (
                          <List.Item
                            actions={[
                              <Button key="restore" type="link" onClick={() => handleRestore(item)}>恢复</Button>,
                            ]}
                          >
                            <span style={{ color: "#999", fontSize: 12 }}>
                              {i + 1}. {REASON_LABEL[item.reason] ?? item.reason} · {item.polygons[0]?.points.length ?? 0} 个顶点
                            </span>
                          </List.Item>
                        )}
                      />
                    ),
                  }]}
                />
              )}
              {hasExistingData && (
                <Checkbox
                  checked={replaceExisting}
                  onChange={e => setReplaceExisting(e.target.checked)}
                  style={{ marginTop: 12 }}
                >
                  移除该楼层原有分区、文字标注与风险点（{existingZoneCount} 个分区 / {existingRiskPointCount} 个风险点）后导入
                </Checkbox>
              )}
            </div>
          </div>
        </div>
      )}
    </Modal>
  );
}

