import { useEffect, useRef, useState } from "react";
import { Button, Input, InputNumber, message, Radio, Select, Space } from "antd";
import { DeleteOutlined, PlusOutlined } from "@ant-design/icons";
import { useRiskMappingWorkbenchStore } from "@/store/riskMappingWorkbenchStore";
import type { RiskCanvasText, WorkbenchZone } from "@/types/riskMappingWorkbench";
import type { RiskObject, RiskPolygon } from "@/types/riskManagement";
import { polygonCentroid, transformPolygonPoints } from "@/utils/riskMappingGeometry";
import { transformRegionsAroundCenter } from "@/utils/riskMappingMarquee";
import { RISK_LEVEL_COLORS } from "@/utils/riskMethodEngine";
import { zoneDisplayColor, zoneDisplayLevel } from "@/utils/zoneDisplay";

const LEVEL_CHOICES: [string, string][] = [
  ["重大", RISK_LEVEL_COLORS["重大"]],
  ["较大", RISK_LEVEL_COLORS["较大"]],
  ["一般", RISK_LEVEL_COLORS["一般"]],
  ["低", RISK_LEVEL_COLORS["低"]],
];

type RiskPointDraft = Pick<
  RiskObject,
  "id" | "name" | "category" | "location" | "description" | "location_x" | "location_y" | "zone_id"
>;

export default function WorkbenchPropertiesPanel() {
  const zones = useRiskMappingWorkbenchStore(s => s.zones);
  const riskPoints = useRiskMappingWorkbenchStore(s => s.riskPoints);
  const pendingRegions = useRiskMappingWorkbenchStore(s => s.pendingRegions);
  const texts = useRiskMappingWorkbenchStore(s => s.texts);
  const selectedZoneId = useRiskMappingWorkbenchStore(s => s.selectedZoneId);
  const selectedRegionIds = useRiskMappingWorkbenchStore(s => s.selectedRegionIds);
  const selectedRegionId = selectedRegionIds[0] ?? null;
  const selectedRiskPointId = useRiskMappingWorkbenchStore(s => s.selectedRiskPointId);
  const selectedTextId = useRiskMappingWorkbenchStore(s => s.selectedTextId);
  const setState = useRiskMappingWorkbenchStore.setState;
  const setSnapshot = useRiskMappingWorkbenchStore.getState().setSnapshot;
  const commit = useRiskMappingWorkbenchStore.getState().commit;
  const [textContent, setTextContent] = useState("");
  const [regionZoneId, setRegionZoneId] = useState<string | null>(null);
  const [targetZoneId, setTargetZoneId] = useState<string | null>(null);
  const [pointDraft, setPointDraft] = useState<RiskPointDraft | null>(null);
  const [regionScale, setRegionScale] = useState(100);
  const [regionRotation, setRegionRotation] = useState(0);
  const zone = zones.find(z => z.id === selectedZoneId);
  const autoBaseRef = useRef<
    Map<
      string,
      Pick<
        WorkbenchZone,
        "effective_color" | "inherent_effective_color" | "max_risk_level" | "inherent_max_level"
      >
    >
  >(new Map());
  const zoneColorMode = zone?.floor_plan_polygon?.level_mode ?? "auto";
  const levelPreview = zone
    ? `${zoneDisplayLevel(zone)}风险${zoneColorMode === "manual" ? "（手动指定）" : "（自动）"}`
    : "";
  const zoneColorPreview = zone ? zoneDisplayColor(zone, "current") : "#d9d9d9";
  const multiSelectMode = selectedRegionIds.length > 1;
  const selectedPolygonEntries = (() => {
    if (!multiSelectMode) return [] as { zoneId: string; polygon: RiskPolygon }[];
    return selectedRegionIds.flatMap(id => {
      if (!id.startsWith("zone:")) return [];
      const body = id.slice("zone:".length);
      const separator = body.indexOf(":");
      const zoneId = body.slice(0, separator);
      const polygonId = body.slice(separator + 1);
      const target = zones.find(z => z.id === zoneId);
      const polygon = target?.floor_plan_polygon?.polygons.find(p => p.id === polygonId);
      return polygon ? [{ zoneId, polygon }] : [];
    });
  })();
  const multiCenter = selectedPolygonEntries.length
    ? polygonCentroid(selectedPolygonEntries.flatMap(e => e.polygon.points))
    : null;
  const selectedPending = selectedRegionId?.startsWith("pending:")
    ? pendingRegions.find(r => r.id === selectedRegionId.slice("pending:".length)) ?? null
    : null;
  const selectedZonePolygon = selectedRegionId?.startsWith("zone:")
    ? (() => {
        const body = selectedRegionId.slice("zone:".length);
        const separator = body.indexOf(":");
        const zid = body.slice(0, separator);
        const pid = body.slice(separator + 1);
        return {
          zoneId: zid,
          polygonId: pid,
          zone: zones.find(z => z.id === zid) ?? null,
          polygon: zones.find(z => z.id === zid)?.floor_plan_polygon?.polygons.find(p => p.id === pid) ?? null,
        };
      })()
    : null;
  const selectedText = texts.find(t => t.id === selectedTextId) ?? null;

  useEffect(() => {
    setRegionZoneId(selectedPending ? (selectedZoneId ?? zones[0]?.id ?? null) : null);
  }, [selectedRegionId, selectedPending, selectedZoneId, zones]);

  useEffect(() => {
    setRegionScale(100);
    setRegionRotation(0);
  }, [selectedRegionId]);

  useEffect(() => {
    setTargetZoneId(null);
  }, [selectedRegionId]);

  useEffect(() => {
    const point = riskPoints.find(p => p.id === selectedRiskPointId);
    setPointDraft(
      point
        ? {
            id: point.id,
            name: point.name,
            category: point.category,
            location: point.location,
            description: point.description,
            location_x: point.location_x,
            location_y: point.location_y,
            zone_id: point.zone_id,
          }
        : null,
    );
  }, [selectedRiskPointId, riskPoints]);

  const updateZone = (patch: Partial<WorkbenchZone>) => {
    if (!zone) return;
    commit();
    setSnapshot({ zones: useRiskMappingWorkbenchStore.getState().zones.map(z => (z.id === zone.id ? { ...z, ...patch } : z)) });
  };

  const setZoneColorMode = (mode: "auto" | "manual", riskLevel?: "重大" | "较大" | "一般" | "低") => {
    if (!zone) return;
    const polygon = zone.floor_plan_polygon || {
      version: 2,
      level_mode: "auto" as const,
      risk_level: null,
      polygons: [],
    };
    if (mode === "manual") {
      if (!autoBaseRef.current.has(zone.id)) {
        autoBaseRef.current.set(zone.id, {
          effective_color: zone.effective_color,
          inherent_effective_color: zone.inherent_effective_color,
          max_risk_level: zone.max_risk_level,
          inherent_max_level: zone.inherent_max_level,
        });
      }
      updateZone({
        floor_plan_polygon: {
          ...polygon,
          level_mode: "manual",
          risk_level: riskLevel ?? polygon.risk_level ?? "较大",
        },
      });
      return;
    }
    const base = autoBaseRef.current.get(zone.id);
    if (base) {
      autoBaseRef.current.delete(zone.id);
      updateZone({
        floor_plan_polygon: { ...polygon, level_mode: "auto", risk_level: null },
        ...base,
      });
    } else {
      message.info("已切换为跟随自动：保存后将按分区风险对象最大等级重新着色。");
      updateZone({ floor_plan_polygon: { ...polygon, level_mode: "auto", risk_level: null } });
    }
  };

  const applyMultiTransform = (options: {
    scale?: number;
    rotationDeg?: number;
    flipX?: boolean;
    flipY?: boolean;
  }) => {
    if (!multiCenter || !selectedPolygonEntries.length) return;
    const transformed = transformRegionsAroundCenter(
      selectedPolygonEntries.map(e => e.polygon),
      options,
      multiCenter,
    );
    const byId = new Map(transformed.map(t => [t.id, t.points]));
    const store = useRiskMappingWorkbenchStore.getState();
    commit();
    setSnapshot({
      zones: store.zones.map(z => {
        if (!z.floor_plan_polygon) return z;
        return {
          ...z,
          floor_plan_polygon: {
            ...z.floor_plan_polygon,
            polygons: z.floor_plan_polygon.polygons.map(p =>
              byId.has(p.id) ? { ...p, points: byId.get(p.id)! } : p,
            ),
          },
        };
      }),
    });
  };

  const bindSelectedPending = () => {
    if (!selectedPending || !regionZoneId) return;
    const target = zones.find(z => z.id === regionZoneId);
    if (!target) return;
    const polygon = target.floor_plan_polygon || { version: 2, level_mode: "auto" as const, risk_level: null, polygons: [] };
    commit();
    setSnapshot({
      zones: useRiskMappingWorkbenchStore.getState().zones.map(z =>
        z.id === target.id
          ? {
              ...z,
              floor_plan_polygon: {
                ...polygon,
                polygons: [
                  ...polygon.polygons,
                  {
                    id: selectedPending.id,
                    label: `${target.name}-区域${polygon.polygons.length + 1}`,
                    points: selectedPending.points,
                  },
                ],
              },
            }
          : z,
      ),
      pendingRegions: useRiskMappingWorkbenchStore.getState().pendingRegions.filter(r => r.id !== selectedPending.id),
    });
    setState({ selectedRegionIds: [], selectedZoneId: target.id });
  };

  const moveSelectedPolygon = () => {
    if (!selectedZonePolygon || !targetZoneId || targetZoneId === selectedZonePolygon.zoneId) return;
    const sourceZone = zones.find(z => z.id === selectedZonePolygon.zoneId);
    const targetZone = zones.find(z => z.id === targetZoneId);
    const polygon = sourceZone?.floor_plan_polygon?.polygons.find(p => p.id === selectedZonePolygon.polygonId);
    if (!sourceZone || !targetZone || !polygon) return;
    const targetPolygon = targetZone.floor_plan_polygon || { version: 2, level_mode: "auto" as const, risk_level: null, polygons: [] };
    const targetPolygonId = targetPolygon.polygons.some(p => p.id === polygon.id)
      ? `${polygon.id}-moved-${Date.now().toString(36)}`
      : polygon.id;
    commit();
    setSnapshot({
      zones: useRiskMappingWorkbenchStore.getState().zones.map(z => {
        if (z.id === sourceZone.id && z.floor_plan_polygon) {
          return {
            ...z,
            floor_plan_polygon: {
              ...z.floor_plan_polygon,
              polygons: z.floor_plan_polygon.polygons.filter(p => p.id !== polygon.id),
            },
          };
        }
        if (z.id === targetZone.id) {
          return {
            ...z,
            floor_plan_polygon: {
              ...targetPolygon,
              polygons: [...targetPolygon.polygons, { ...polygon, id: targetPolygonId }],
            },
          };
        }
        return z;
      }),
    });
    setState({ selectedRegionIds: [] });
  };

  const transformSelectedRegion = (
    options: { scale?: number; rotationDeg?: number; flipX?: boolean; flipY?: boolean } = {},
  ) => {
    const scale = options.scale ?? regionScale / 100;
    const rotationDeg = options.rotationDeg ?? regionRotation;
    const flipX = options.flipX ?? false;
    const flipY = options.flipY ?? false;
    if (selectedPending) {
      commit();
      setSnapshot({
        pendingRegions: useRiskMappingWorkbenchStore.getState().pendingRegions.map(r =>
          r.id === selectedPending.id
            ? {
                ...r,
                points: transformPolygonPoints(r.points, { scale, rotationDeg, flipX, flipY }),
              }
            : r,
        ),
      });
    } else if (selectedZonePolygon?.zoneId && selectedZonePolygon.polygonId) {
      commit();
      setSnapshot({
        zones: useRiskMappingWorkbenchStore.getState().zones.map(z => {
          if (z.id !== selectedZonePolygon.zoneId || !z.floor_plan_polygon) return z;
          return {
            ...z,
            floor_plan_polygon: {
              ...z.floor_plan_polygon,
              polygons: z.floor_plan_polygon.polygons.map(p =>
                p.id === selectedZonePolygon.polygonId
                  ? {
                      ...p,
                      points: transformPolygonPoints(p.points, { scale, rotationDeg, flipX, flipY }),
                    }
                  : p,
              ),
            },
          };
        }),
      });
    }
    setRegionScale(100);
    setRegionRotation(0);
  };

  const saveRiskPoint = () => {
    if (!pointDraft) return;
    commit();
    setSnapshot({
      riskPoints: useRiskMappingWorkbenchStore.getState().riskPoints.map(p =>
        p.id === pointDraft.id
          ? {
              ...p,
              name: pointDraft.name.trim() || p.name,
              category: pointDraft.category,
              location: pointDraft.location,
              description: pointDraft.description,
              location_x: pointDraft.location_x ?? 50,
              location_y: pointDraft.location_y ?? 50,
              zone_id: pointDraft.zone_id,
              updated_at: new Date().toISOString(),
            }
          : p,
      ),
    });
  };

  const addText = () => {
    if (!textContent.trim()) return;
    const item: RiskCanvasText = {
      id: `text-${Date.now()}`,
      content: textContent.trim(),
      x: 50,
      y: 50,
      font_size: 14,
      color: "#333333",
      rotation: 0,
      sort_order: texts.length,
    };
    commit();
    setSnapshot({ texts: [...useRiskMappingWorkbenchStore.getState().texts, item] });
    setTextContent("");
    setState({ selectedTextId: item.id, selectedRiskPointId: null, selectedRegionIds: [] });
  };

  return (
    <div style={{ background: "#fff", borderRadius: 8, padding: 12, overflow: "auto" }}>
      <h4 style={{ fontSize: 14, marginBottom: 12 }}>属性</h4>

      {multiSelectMode && (
        <div style={{ border: "1px solid #8b5cf6", borderRadius: 6, padding: 8, marginBottom: 12 }}>
          <strong>已选中 {selectedRegionIds.length} 个区域</strong>
          <div style={{ display: "flex", alignItems: "center", gap: 8, marginTop: 6 }}>
            <span style={{ fontSize: 12, color: "#666" }}>缩放</span>
            <InputNumber
              style={{ flex: 1 }}
              min={10}
              max={500}
              value={regionScale}
              onChange={v => setRegionScale(v ?? 100)}
              addonAfter="%"
            />
          </div>
          <div style={{ display: "flex", alignItems: "center", gap: 8, marginTop: 6 }}>
            <span style={{ fontSize: 12, color: "#666" }}>旋转</span>
            <InputNumber
              style={{ flex: 1 }}
              min={-360}
              max={360}
              value={regionRotation}
              onChange={v => setRegionRotation(v ?? 0)}
              addonAfter="°"
            />
          </div>
          <Button
            block
            type="primary"
            style={{ marginTop: 6 }}
            onClick={() => applyMultiTransform({ scale: regionScale / 100, rotationDeg: regionRotation })}
          >
            应用变换
          </Button>
          <Space.Compact style={{ width: "100%", marginTop: 6 }}>
            <Button style={{ width: "50%" }} onClick={() => applyMultiTransform({ flipX: true })}>
              水平翻转
            </Button>
            <Button style={{ width: "50%" }} onClick={() => applyMultiTransform({ flipY: true })}>
              垂直翻转
            </Button>
          </Space.Compact>
          <Button
            danger
            block
            style={{ marginTop: 6 }}
            icon={<DeleteOutlined />}
            onClick={() => useRiskMappingWorkbenchStore.getState().deleteSelectedRegions()}
          >
            删除选中区域
          </Button>
        </div>
      )}

      {!multiSelectMode && selectedPending && (
        <div style={{ border: "1px dashed #fa8c16", borderRadius: 6, padding: 8, marginBottom: 12 }}>
          <strong>待绑定区域</strong>
          <div style={{ fontSize: 12, color: "#8c8c8c", margin: "4px 0" }}>{selectedPending.points.length} 个顶点</div>
          <Select
            style={{ width: "100%" }}
            placeholder="选择所属分区"
            value={regionZoneId || undefined}
            options={zones.map(z => ({ value: z.id, label: z.name }))}
            onChange={setRegionZoneId}
          />
          <Button block type="primary" style={{ marginTop: 6 }} disabled={!regionZoneId} onClick={bindSelectedPending}>
            绑定到分区
          </Button>
          <Button
            danger
            block
            style={{ marginTop: 6 }}
            icon={<DeleteOutlined />}
            onClick={() => {
              commit();
              useRiskMappingWorkbenchStore.getState().deletePendingRegion(selectedPending.id);
            }}
          >
            删除区域
          </Button>
        </div>
      )}

      {!multiSelectMode && selectedZonePolygon?.polygon && selectedZonePolygon.zone && (
        <div style={{ border: "1px solid #d9d9d9", borderRadius: 6, padding: 8, marginBottom: 12 }}>
          <strong>已绑定区域</strong>
          <div style={{ fontSize: 12, color: "#8c8c8c", margin: "4px 0" }}>
            当前分区：{selectedZonePolygon.zone.name} · {selectedZonePolygon.polygon.points.length} 个顶点
          </div>
          <Select
            style={{ width: "100%" }}
            placeholder="移动到其他分区"
            value={targetZoneId || undefined}
            options={zones.map(z => ({ value: z.id, label: z.name }))}
            onChange={setTargetZoneId}
          />
          <Button
            block
            style={{ marginTop: 6 }}
            disabled={!targetZoneId || targetZoneId === selectedZonePolygon.zoneId}
            onClick={moveSelectedPolygon}
          >
            移动到分区
          </Button>
          <Button
            danger
            block
            style={{ marginTop: 6 }}
            icon={<DeleteOutlined />}
            onClick={() => {
              commit();
              useRiskMappingWorkbenchStore.getState().deleteZonePolygon(
                selectedZonePolygon.zoneId,
                selectedZonePolygon.polygonId,
              );
            }}
          >
            删除区域
          </Button>
        </div>
      )}

      {!multiSelectMode && (selectedPending || selectedZonePolygon) && (
        <div style={{ border: "1px solid #8b5cf6", borderRadius: 6, padding: 8, marginBottom: 12 }}>
          <strong>自由变换</strong>
          <div style={{ display: "flex", alignItems: "center", gap: 8, marginTop: 6 }}>
            <span style={{ fontSize: 12, color: "#666" }}>缩放</span>
            <InputNumber
              style={{ flex: 1 }}
              min={10}
              max={500}
              value={regionScale}
              onChange={v => setRegionScale(v ?? 100)}
              addonAfter="%"
            />
          </div>
          <div style={{ display: "flex", alignItems: "center", gap: 8, marginTop: 6 }}>
            <span style={{ fontSize: 12, color: "#666" }}>旋转</span>
            <InputNumber
              style={{ flex: 1 }}
              min={-360}
              max={360}
              value={regionRotation}
              onChange={v => setRegionRotation(v ?? 0)}
              addonAfter="°"
            />
          </div>
          <Button block type="primary" style={{ marginTop: 6 }} onClick={() => transformSelectedRegion()}>
            应用变换
          </Button>
          <Space.Compact style={{ width: "100%", marginTop: 6 }}>
            <Button style={{ width: "50%" }} onClick={() => transformSelectedRegion({ flipX: true })}>
              水平翻转
            </Button>
            <Button style={{ width: "50%" }} onClick={() => transformSelectedRegion({ flipY: true })}>
              垂直翻转
            </Button>
          </Space.Compact>
        </div>
      )}

      {!zone ? (
        <div style={{ color: "#999" }}>请先选择分区</div>
      ) : (
        <>
          <Input value={zone.name} onChange={e => updateZone({ name: e.target.value })} />
          <div style={{ borderTop: "1px solid #f0f0f0", marginTop: 8, paddingTop: 8 }}>
            <div style={{ fontSize: 13, fontWeight: 600, marginBottom: 6 }}>分区颜色</div>
            <div style={{ display: "flex", alignItems: "center", gap: 8, marginBottom: 6 }}>
              <span
                style={{
                  width: 18,
                  height: 18,
                  borderRadius: 4,
                  background: zoneColorPreview,
                  display: "inline-block",
                  border: "1px solid #d9d9d9",
                }}
              />
              <span style={{ fontSize: 12, color: "#666" }}>{levelPreview}</span>
            </div>
            <Radio.Group
              size="small"
              value={zoneColorMode}
              onChange={e => setZoneColorMode(e.target.value as "auto" | "manual")}
              options={[
                { value: "auto", label: "跟随自动" },
                { value: "manual", label: "手动指定" },
              ]}
            />
            {zone.floor_plan_polygon?.level_mode === "manual" && (
              <div style={{ display: "flex", gap: 6, marginTop: 8, flexWrap: "wrap" }}>
                {LEVEL_CHOICES.map(([level, color]) => (
                  <button
                    key={level}
                    type="button"
                    onClick={() => setZoneColorMode("manual", level as "重大" | "较大" | "一般" | "低")}
                    style={{
                      display: "inline-flex",
                      alignItems: "center",
                      gap: 4,
                      padding: "4px 8px",
                      borderRadius: 6,
                      border:
                        zone.floor_plan_polygon?.risk_level === level ? "2px solid #1677ff" : "1px solid #d9d9d9",
                      background: color,
                      color: level === "一般" ? "#333" : "#fff",
                      cursor: "pointer",
                      fontSize: 12,
                    }}
                  >
                    {level}
                  </button>
                ))}
              </div>
            )}
            <div style={{ fontSize: 12, color: "#999", marginTop: 6 }}>
              手动指定后现有/固有模式均显示该颜色，不随风险对象变化。
            </div>
          </div>
          <Input.TextArea
            style={{ marginTop: 8 }}
            rows={3}
            value={zone.description || ""}
            onChange={e => updateZone({ description: e.target.value })}
          />
          <Button
            danger
            block
            style={{ marginTop: 8 }}
            icon={<DeleteOutlined />}
            onClick={() => {
              commit();
              useRiskMappingWorkbenchStore.getState().deleteZone(zone.id);
            }}
          >
            删除分区
          </Button>
        </>
      )}

      <h4 style={{ fontSize: 14, marginTop: 16 }}>风险点</h4>
      {riskPoints.map(p => (
        <div
          key={p.id}
          style={{
            marginTop: 4,
            padding: 4,
            borderRadius: 4,
            cursor: "pointer",
            border: selectedRiskPointId === p.id ? "1px solid #1677ff" : "1px solid transparent",
          }}
          onClick={() => setState({ selectedRiskPointId: p.id, selectedRegionIds: [], selectedTextId: null })}
        >
          <div style={{ display: "flex", justifyContent: "space-between" }}>
            <span>{p.name}</span>
            <Button
              size="small"
              type="text"
              icon={<DeleteOutlined />}
              onClick={e => {
                e.stopPropagation();
                commit();
                useRiskMappingWorkbenchStore.getState().deleteRiskPoint(p.id);
              }}
            />
          </div>
          {selectedRiskPointId === p.id && pointDraft && (
            <div style={{ borderTop: "1px solid #e8e8e8", marginTop: 6, paddingTop: 6 }}>
              <Input
                value={pointDraft.name}
                onChange={e => setPointDraft({ ...pointDraft, name: e.target.value })}
                placeholder="风险点名称"
              />
              <Input
                style={{ marginTop: 6 }}
                value={pointDraft.category || ""}
                onChange={e => setPointDraft({ ...pointDraft, category: e.target.value })}
                placeholder="类别"
              />
              <Input
                style={{ marginTop: 6 }}
                value={pointDraft.location || ""}
                onChange={e => setPointDraft({ ...pointDraft, location: e.target.value })}
                placeholder="位置描述"
              />
              <Input.TextArea
                style={{ marginTop: 6 }}
                rows={2}
                value={pointDraft.description || ""}
                onChange={e => setPointDraft({ ...pointDraft, description: e.target.value })}
                placeholder="说明"
              />
              <Space.Compact style={{ width: "100%", marginTop: 6 }}>
                <InputNumber
                  style={{ width: "50%" }}
                  min={0}
                  max={100}
                  value={pointDraft.location_x ?? 50}
                  onChange={v => setPointDraft({ ...pointDraft, location_x: v ?? 50 })}
                />
                <InputNumber
                  style={{ width: "50%" }}
                  min={0}
                  max={100}
                  value={pointDraft.location_y ?? 50}
                  onChange={v => setPointDraft({ ...pointDraft, location_y: v ?? 50 })}
                />
              </Space.Compact>
              <Select
                style={{ width: "100%", marginTop: 6 }}
                placeholder="绑定分区"
                value={pointDraft.zone_id || undefined}
                options={zones.map(z => ({ value: z.id, label: z.name }))}
                onChange={zone_id => setPointDraft({ ...pointDraft, zone_id })}
              />
              <Button block type="primary" style={{ marginTop: 6 }} onClick={saveRiskPoint}>
                保存风险点
              </Button>
              <Button
                danger
                block
                style={{ marginTop: 6 }}
                icon={<DeleteOutlined />}
                onClick={() => {
                  commit();
                  useRiskMappingWorkbenchStore.getState().deleteRiskPoint(p.id);
                }}
              >
                删除风险点
              </Button>
            </div>
          )}
        </div>
      ))}

      <h4 style={{ fontSize: 14, marginTop: 16 }}>文字标注</h4>
      <Space.Compact style={{ width: "100%" }}>
        <Input value={textContent} onChange={e => setTextContent(e.target.value)} placeholder="标注内容" />
        <Button icon={<PlusOutlined />} onClick={addText} />
      </Space.Compact>
      {texts.map(t => (
        <div
          key={t.id}
          onClick={() => setState({ selectedTextId: t.id, selectedRiskPointId: null, selectedRegionIds: [] })}
          style={{
            display: "flex",
            justifyContent: "space-between",
            alignItems: "center",
            fontSize: 12,
            marginTop: 4,
            cursor: "pointer",
            border: selectedTextId === t.id ? "1px solid #1677ff" : "1px solid transparent",
            borderRadius: 4,
            padding: "2px 4px",
          }}
        >
          <span
            style={{
              overflow: "hidden",
              textOverflow: "ellipsis",
              whiteSpace: "nowrap",
              color: t.color,
              fontSize: t.font_size,
            }}
          >
            {t.content}
          </span>
          <Button
            size="small"
            type="text"
            icon={<DeleteOutlined />}
            onClick={e => {
              e.stopPropagation();
              commit();
              useRiskMappingWorkbenchStore.getState().deleteText(t.id);
            }}
          />
        </div>
      ))}
      {selectedText && (
        <Button
          block
          style={{ marginTop: 8 }}
          onClick={() => {
            commit();
            useRiskMappingWorkbenchStore.getState().deleteText(selectedText.id);
          }}
        >
          删除选中文字
        </Button>
      )}
    </div>
  );
}

