import { useState, useEffect, useCallback, type ReactNode } from "react";
import { useQuery, useQueryClient } from "@tanstack/react-query";
import { listEnterprises } from "@/services/enterpriseService";
import { useAuth } from "@/contexts/useAuth";
import { EnterpriseContext } from "@/contexts/useCurrentEnterprise";

export function EnterpriseProvider({ children }: { children: ReactNode }) {
  const { isAuthenticated } = useAuth();
  const [currentEnterpriseId, setCurrentEnterpriseId] = useState<string | null>(
    () => localStorage.getItem("currentEnterpriseId")
  );
  const queryClient = useQueryClient();

  const { data: enterprisesData, isLoading } = useQuery({
    queryKey: ["enterprises"],
    queryFn: async () => {
      const res = await listEnterprises({ page_size: 100 });
      return res.data.items;
    },
    // 未认证时不发起企业列表请求（登录页也会挂载本 Provider，避免无 token 时 401 刷屏）
    enabled: isAuthenticated,
  });

  const enterprises = enterprisesData || [];

  const setCurrentEnterprise = useCallback((id: string) => {
    localStorage.setItem("currentEnterpriseId", id);
    setCurrentEnterpriseId(id);
  }, []);

  // 如果当前企业不在列表中，自动选择第一个
  useEffect(() => {
    if (enterprises.length > 0) {
      const exists = enterprises.some((e) => e.id === currentEnterpriseId);
      if (!exists) {
        setCurrentEnterprise(enterprises[0].id);
      }
    }
  }, [enterprises, currentEnterpriseId, setCurrentEnterprise]);

  const refreshEnterprises = useCallback(async () => {
    await queryClient.invalidateQueries({ queryKey: ["enterprises"] });
  }, [queryClient]);

  return (
    <EnterpriseContext.Provider
      value={{ currentEnterpriseId, enterprises, isLoading, setCurrentEnterprise, refreshEnterprises }}
    >
      {children}
    </EnterpriseContext.Provider>
  );
}

import { useEffect, useCallback } from "react";
import { Outlet, useLocation, useNavigate } from "react-router-dom";
import { AnimatePresence, motion } from "framer-motion";
import TabBar from "@/mobile/components/ui/TabBar";
import NetworkStatusBanner from "@/mobile/components/ui/NetworkStatusBanner";
import { ErrorBoundary } from "@/mobile/components/ui/ErrorBoundary";
import { useAppStore } from "@/mobile/store/appStore";
import { stripAppBase } from "@/utils/platform";
import {
  LayoutDashboard,
  Building2,
  FileText,
  Settings,
} from "lucide-react";

// Tab 路由匹配规则
const TAB_PATTERNS: Record<string, RegExp> = {
  dashboard: /^\/m(\/dashboard)?$/,
  enterprises: /^\/m\/enterprises/,
  plans: /^\/m\/plans/,
  settings: /^\/m\/settings/,
};

const TAB_ROUTES: Record<string, string> = {
  dashboard: "/m/dashboard",
  enterprises: "/m/enterprises",
  plans: "/m/plans",
  settings: "/m/settings",
};

// 判断哪些路由应该隐藏 TabBar
const HIDE_TABBAR_PATTERNS = [
  /^\/m\/login$/,
  /^\/m\/register$/,
  /^\/m\/splash$/,
  /^\/m\/chat$/,
];

function shouldHideTabBar(pathname: string): boolean {
  return HIDE_TABBAR_PATTERNS.some((p) => p.test(pathname));
}

const TAB_ITEMS = [
  { key: "dashboard", icon: <LayoutDashboard size={24} />, label: "工作台" },
  { key: "enterprises", icon: <Building2 size={24} />, label: "企业" },
  { key: "plans", icon: <FileText size={24} />, label: "预案" },
  { key: "settings", icon: <Settings size={24} />, label: "设置" },
];

// 页面转场动画
const pageVariants = {
  initial: { opacity: 0, x: 20 },
  animate: { opacity: 1, x: 0 },
  exit: { opacity: 0, x: -20 },
};

export default function MainTabsLayout() {
  const location = useLocation();
  const navigate = useNavigate();
  const { activeTab, setActiveTab } = useAppStore();
  const pathname = stripAppBase(location.pathname);
  const hideTabBar = shouldHideTabBar(pathname);

  // 根据路由自动更新 activeTab
  useEffect(() => {
    for (const [tab, pattern] of Object.entries(TAB_PATTERNS)) {
      if (pattern.test(pathname)) {
        if (activeTab !== tab) {
          setActiveTab(tab as typeof activeTab);
        }
        break;
      }
    }
  }, [pathname, setActiveTab, activeTab]);

  // Tab 点击 → 路由跳转
  const handleTabChange = useCallback((key: string) => {
    setActiveTab(key as typeof activeTab);
    navigate(TAB_ROUTES[key] || "/m/dashboard");
  }, [navigate, setActiveTab, activeTab]);

  return (
    <ErrorBoundary>
      <div className="flex flex-col h-dvh bg-neutral-50">
        <NetworkStatusBanner />
        <main
          className="flex-1 overflow-y-auto"
          style={{ paddingBottom: hideTabBar ? 0 : "var(--tabbar-height)" }}
        >
          <AnimatePresence mode="wait">
            <motion.div
              key={pathname}
              variants={pageVariants}
              initial="initial"
              animate="animate"
              exit="exit"
              transition={{ duration: 0.2, ease: "easeOut" }}
            >
              <Outlet />
            </motion.div>
          </AnimatePresence>
        </main>
        {!hideTabBar && (
          <TabBar
            items={TAB_ITEMS}
            activeKey={activeTab}
            onChange={handleTabChange}
          />
        )}
      </div>
    </ErrorBoundary>
  );
}

import { useState, useMemo } from "react";
import { useNavigate } from "react-router-dom";
import { useQuery } from "@tanstack/react-query";
import {
  ChevronDown, ChevronRight, FileText,
  Target, Factory, Check,
} from "lucide-react";
import { motion } from "framer-motion";
import NavBar from "@/mobile/components/ui/NavBar";
import SafeArea from "@/mobile/components/ui/SafeArea";
import Card from "@/mobile/components/ui/Card";
import Badge from "@/mobile/components/ui/Badge";
import Button from "@/mobile/components/ui/Button";
import Chip from "@/mobile/components/ui/Chip";
import ProgressBar from "@/mobile/components/ui/ProgressBar";
import Skeleton from "@/mobile/components/ui/Skeleton";
import EmptyState from "@/mobile/components/ui/EmptyState";
import BottomSheet from "@/mobile/components/ui/BottomSheet";
import FAB from "@/mobile/components/ui/FAB";
import { useToast } from "@/mobile/components/ui/useToast";
import { useAppStore } from "@/mobile/store/appStore";
import { getDashboard } from "@/services/dashboardService";
import { listEnterprises } from "@/services/enterpriseService";
import { getEnterpriseCompletion } from "@/services/onboardingService";
import { getEnterprisePlanSummary } from "@/services/planService";
import { fromNow } from "@/utils/formatters";

const PLAN_TYPE_LABELS: Record<string, string> = {
  comprehensive: "综合",
  special: "专项",
  onsite: "现场",
};

const PLAN_TYPE_COLORS: Record<string, "info" | "warning" | "success"> = {
  comprehensive: "info",
  special: "warning",
  onsite: "success",
};

const QUICK_ACTIONS = [
  {
    type: "comprehensive",
    icon: <FileText size={20} />,
    title: "新建综合应急预案",
    desc: "从企业信息自动生成完整框架",
  },
  {
    type: "special",
    icon: <Target size={20} />,
    title: "新建专项应急预案",
    desc: "针对特定事故类型（火灾、触电等）",
  },
  {
    type: "onsite",
    icon: <Factory size={20} />,
    title: "新建现场处置方案",
    desc: "一线操作卡片式应急处置步骤",
  },
];

export default function DashboardScreen() {
  const navigate = useNavigate();
  const { showToast } = useToast();
  const {
    currentEnterpriseId, currentEnterpriseName,
    setCurrentEnterprise,
  } = useAppStore();
  const [enterpriseSheetOpen, setEnterpriseSheetOpen] = useState(false);

  // 获取企业列表
  const enterprisesQuery = useQuery({
    queryKey: ["enterprises"],
    queryFn: async () => {
      const res = await listEnterprises({ page: 1, page_size: 100 });
      return res.data.items;
    },
    staleTime: 60000,
  });

  const enterprises = enterprisesQuery.data ?? [];

  // 自动选择当前企业
  const activeEnterpriseId = useMemo(() => {
    if (currentEnterpriseId) return currentEnterpriseId;
    if (enterprises.length > 0) {
      setCurrentEnterprise(enterprises[0].id, enterprises[0].name);
      return enterprises[0].id;
    }
    return null;
  }, [currentEnterpriseId, enterprises, setCurrentEnterprise]);

  const activeEnterpriseName = useMemo(() => {
    if (currentEnterpriseName) return currentEnterpriseName;
    if (enterprises.length > 0) return enterprises[0].name;
    return null;
  }, [currentEnterpriseName, enterprises]);

  // 获取 Dashboard 数据
  const dashboardQuery = useQuery({
    queryKey: ["dashboard", activeEnterpriseId],
    queryFn: getDashboard,
    enabled: !!activeEnterpriseId,
    staleTime: 60000,
    refetchOnMount: true,
  });

  // 获取预案汇总
  const summaryQuery = useQuery({
    queryKey: ["enterprise-plan-summary", activeEnterpriseId],
    queryFn: getEnterprisePlanSummary,
    enabled: !!activeEnterpriseId,
    staleTime: 60000,
  });

  // 获取企业数据完成度
  const completionQuery = useQuery({
    queryKey: ["completion", activeEnterpriseId],
    queryFn: () => getEnterpriseCompletion(activeEnterpriseId!),
    enabled: !!activeEnterpriseId,
    staleTime: 60000,
  });

  const stats = dashboardQuery.data?.stats;
  const recentPlans = dashboardQuery.data?.recent_plans ?? [];
  const isLoading = dashboardQuery.isLoading || summaryQuery.isLoading;
  const undoneModules = (completionQuery.data?.modules ?? []).filter(m => !m.done);

  // 计算当前企业的预案统计
  const planStats = useMemo(() => {
    const s = summaryQuery.data?.find(e => e.enterprise_id === activeEnterpriseId);
    return {
      total: s?.total ?? 0,
      comprehensive: s?.comprehensive_count ?? 0,
      special: s?.special_count ?? 0,
      onsite: s?.onsite_count ?? 0,
    };
  }, [summaryQuery.data, activeEnterpriseId]);

  const handleSelectEnterprise = (id: string, name: string) => {
    setCurrentEnterprise(id, name);
    setEnterpriseSheetOpen(false);
    showToast?.({ type: "info", message: `已切换到 ${name}` });
  };

  const handleQuickAction = (type: string) => {
    if (!activeEnterpriseId) {
      showToast?.({ type: "warning", message: "请先添加企业" });
      return;
    }
    navigate(`/m/plans/new?enterprise_id=${activeEnterpriseId}&type=${type}`);
  };

  const handleCompletionAction = () => {
    if (!activeEnterpriseId) return;
    if (undoneModules.length === 0) {
      navigate(`/m/plans/new?enterprise_id=${activeEnterpriseId}`);
    } else {
      navigate(`/m/enterprises/${activeEnterpriseId}`);
    }
  };

  const SPEED_DIAL_ACTIONS = QUICK_ACTIONS.map(a => ({
    icon: a.icon,
    label: a.title.replace("新建", "").trim(),
    onPress: () => handleQuickAction(a.type),
  }));

  // 如果正在加载，显示骨架屏
  if (isLoading && !dashboardQuery.data) {
    return (
      <SafeArea className="bg-neutral-50 min-h-dvh">
        <NavBar title="工作台" largeTitle />
        <div className="px-md space-y-md">
          <Skeleton variant="text" className="h-4 w-48" />
          <div className="flex gap-md overflow-hidden">
            {[1, 2, 3].map(i => (
              <Skeleton key={i} variant="card" className="min-w-[116px] h-24" />
            ))}
          </div>
          {[1, 2, 3].map(i => (
            <Skeleton key={`act-${i}`} variant="list-item" className="h-14" />
          ))}
          <Skeleton variant="text" className="h-4 w-24 mt-lg" />
          {[1, 2, 3].map(i => (
            <Skeleton key={`rec-${i}`} variant="list-item" className="h-20" />
          ))}
        </div>
      </SafeArea>
    );
  }

  return (
    <SafeArea className="bg-neutral-50 min-h-dvh pb-[calc(var(--tabbar-height)+80px)]">
      <NavBar title="工作台" largeTitle />

      {/* 企业数据完成度卡片 */}
      {/* 加载中：查询 key 含企业 id，切换企业时旧企业数据不会复用，直接显示骨架屏 */}
      {!completionQuery.isError && completionQuery.isLoading && (
        <Card className="mx-md mt-md mb-md bg-primary-50 border border-primary-600">
          <div className="flex items-center justify-between">
            <Skeleton variant="text" className="h-4 w-36" />
            <Skeleton variant="text" className="h-4 w-12" />
          </div>
          <Skeleton variant="text" className="h-1.5 mt-sm" />
          <div className="flex gap-xs mt-sm">
            <Skeleton variant="text" className="h-6 w-16 rounded-full" />
            <Skeleton variant="text" className="h-6 w-16 rounded-full" />
          </div>
        </Card>
      )}

      {completionQuery.isError && !completionQuery.data && (
        <Card className="mx-md mt-md mb-md bg-primary-50 border border-primary-600">
          <div className="flex items-center justify-between">
            <p className="text-body font-semibold text-neutral-900">企业数据完成度</p>
            <Button
              variant="ghost"
              size="sm"
              loading={completionQuery.isFetching}
              onClick={() => completionQuery.refetch()}
            >
              重试
            </Button>
          </div>
          <p className="text-caption text-danger mt-xs">完成度加载失败，请检查网络后重试</p>
        </Card>
      )}

      {completionQuery.data && (
        <Card className="mx-md mt-md mb-md bg-primary-50 border border-primary-600">
          <div className="flex items-center justify-between mb-xs">
            <p className="text-body font-semibold text-neutral-900">企业数据完成度</p>
            <span className="text-h3 font-bold text-primary-600">
              {completionQuery.data.percent}%
            </span>
          </div>
          <ProgressBar percent={completionQuery.data.percent} />
          {undoneModules.length > 0 && (
            <div className="flex flex-wrap gap-xs mt-sm">
              {undoneModules.map((m) => (
                <Chip key={m.key} variant="warning">
                  {m.label}
                </Chip>
              ))}
            </div>
          )}
          <div className="mt-sm">
            <Button size="sm" onClick={handleCompletionAction}>
              {undoneModules.length === 0 ? "去生成预案" : "去补数据"}
            </Button>
          </div>
        </Card>
      )}

      <div className="px-md space-y-md">

        {/* 企业切换器 */}
        <button
          className="flex items-center gap-xs text-left"
          onClick={() => setEnterpriseSheetOpen(true)}
        >
          <span className="text-h3 font-semibold text-neutral-900">
            {activeEnterpriseName ?? "暂未添加企业"}
          </span>
          <ChevronDown size={14} className="text-neutral-400" />
          {!activeEnterpriseId && (
            <span className="text-caption text-primary-600 ml-sm">去添加 →</span>
          )}
        </button>

        {/* 日期 */}
        <p className="text-caption text-neutral-400 -mt-xs">
          {new Date().toLocaleDateString("zh-CN", {
            year: "numeric", month: "long", day: "numeric", weekday: "long",
          })}
        </p>

        {/* 统计卡片组 */}
        <div className="flex gap-md overflow-x-auto snap-x snap-mandatory hide-scrollbar">
          <div className="min-w-[116px] h-24 bg-white rounded-md shadow-card flex flex-col justify-center p-md snap-start">
            <p className="text-display text-primary-600 font-bold">
              {planStats.total}
            </p>
            <p className="text-caption text-neutral-400 mt-xs">预案总数</p>
          </div>
          <div className="min-w-[116px] h-24 bg-white rounded-md shadow-card flex flex-col justify-center p-md snap-start">
            <p className="text-display text-green-600 font-bold">
              {stats?.completed_plan_count ?? 0}
            </p>
            <p className="text-caption text-neutral-400 mt-xs">已完成</p>
          </div>
          <div className="min-w-[116px] h-24 bg-white rounded-md shadow-card flex flex-col justify-center p-md snap-start">
            <p className="text-display text-neutral-900 font-bold">
              {stats?.enterprise_count ?? enterprises.length}
            </p>
            <p className="text-caption text-neutral-400 mt-xs">管理企业</p>
          </div>
        </div>

        {/* 快捷操作 */}
        <div>
          <p className="text-h2 mb-sm">快捷操作</p>
          <div className="space-y-3">
            {QUICK_ACTIONS.map((action) => (
              <motion.div
                key={action.type}
                whileTap={{ scale: 0.99 }}
              >
                <Card
                  pressable
                  className="flex items-center px-md h-14 gap-md"
                  onClick={() => handleQuickAction(action.type)}
                >
                  <div className="w-10 h-10 rounded-full bg-primary-50 flex items-center justify-center text-primary-600 shrink-0">
                    {action.icon}
                  </div>
                  <div className="flex-1 min-w-0">
                    <p className="text-body font-semibold text-neutral-900">
                      {action.title}
                    </p>
                    <p className="text-caption text-neutral-400 truncate">
                      {action.desc}
                    </p>
                  </div>
                  <ChevronRight size={16} className="text-neutral-400 shrink-0" />
                </Card>
              </motion.div>
            ))}
          </div>
        </div>

        {/* 最近编辑 */}
        <div>
          <div className="flex items-center justify-between mb-sm">
            <p className="text-h2">最近编辑</p>
            <button
              className="text-caption text-primary-600"
              onClick={() => navigate("/m/plans")}
            >
              查看全部 →
            </button>
          </div>

          {recentPlans.length === 0 ? (
            <EmptyState
              icon={<FileText size={40} className="text-neutral-300" />}
              title="暂无编辑记录"
              description="创建第一个预案开始使用"
              action={{ label: "新建预案", onPress: () => handleQuickAction("comprehensive") }}
            />
          ) : (
            <div className="space-y-3">
              {recentPlans.slice(0, 5).map((plan) => (
                <motion.div key={plan.id} whileTap={{ scale: 0.99 }}>
                  <Card
                    pressable
                    className="flex items-start gap-md p-md"
                    onClick={() => navigate(`/m/plans/${plan.id}/edit`)}
                  >
                    <div className="flex-1 min-w-0">
                      <p className="text-h3 font-semibold text-neutral-900 truncate">
                        {plan.title}
                      </p>
                      <p className="text-caption text-neutral-400 mt-1">
                        {plan.enterprise_name} · {fromNow(plan.updated_at)}
                      </p>
                      <div className="flex gap-xs mt-2">
                        <Badge variant={PLAN_TYPE_COLORS[plan.plan_type] ?? "default"}>
                          {PLAN_TYPE_LABELS[plan.plan_type] ?? plan.plan_type}
                        </Badge>
                        <Badge
                          variant={plan.status === "completed" ? "success" : plan.status === "generating" ? "info" : "default"}
                        >
                          {plan.status === "completed" ? "已完成" : plan.status === "generating" ? "生成中" : "草稿"}
                        </Badge>
                      </div>
                    </div>
                    <ChevronRight size={16} className="text-neutral-400 mt-1 shrink-0" />
                  </Card>
                </motion.div>
              ))}
            </div>
          )}
        </div>

      </div>

      {/* 企业切换 BottomSheet */}
      <BottomSheet
        open={enterpriseSheetOpen}
        onClose={() => setEnterpriseSheetOpen(false)}
        height="60%"
      >
        <div className="p-md">
          <p className="text-h2 mb-md">选择工作企业</p>
          <div className="space-y-1">
            {enterprises.map((ent) => (
              <button
                key={ent.id}
                className="flex items-center gap-md w-full px-sm py-3 rounded-md active:bg-neutral-50"
                onClick={() => handleSelectEnterprise(ent.id, ent.name)}
              >
                <div className="w-11 h-11 rounded-full bg-primary-50 flex items-center justify-center text-primary-600 font-semibold text-body shrink-0">
                  {ent.name.charAt(0)}
                </div>
                <span className="flex-1 text-left text-body text-neutral-900">
                  {ent.name}
                </span>
                {activeEnterpriseId === ent.id && (
                  <Check size={20} className="text-primary-600 shrink-0" />
                )}
              </button>
            ))}
          </div>
          <button
            className="mt-md w-full py-3 text-center text-body text-primary-600 border-t border-neutral-100 pt-md"
            onClick={() => {
              setEnterpriseSheetOpen(false);
              navigate("/m/enterprises");
            }}
          >
            管理企业 →
          </button>
        </div>
      </BottomSheet>

      {/* FAB */}
      <FAB speedDialActions={SPEED_DIAL_ACTIONS} />
    </SafeArea>
  );
}

import { useState, useRef, useEffect, useCallback } from "react";
import { Input, Button, Typography, Spin, message, Popconfirm } from "antd";
import { SendOutlined, PlusOutlined, DeleteOutlined, MessageOutlined, CloseOutlined } from "@ant-design/icons";
import AppIcon from "@/components/common/AppIcon";
import AiNotConfiguredHint from "@/components/common/AiNotConfiguredHint";
import {
  sendChatMessage,
  fetchConversations,
  createConversation,
  deleteConversation,
  fetchMessages,
  fetchToolCalls,
  type ChatMessage,
  type ChatSSEEvent,
  type Conversation,
  type ToolCallStep,
} from "@/services/chatService";
import MarkdownIt from "markdown-it";
import DOMPurify from "dompurify";
import { aiErrorDisplay } from "@/utils/aiUnavailable";
const md = new MarkdownIt();

const { Text, Paragraph } = Typography;

interface DisplayMessage {
  role: "user" | "assistant" | "function";
  content: string;
  html?: boolean;
  name?: string;
  loading?: boolean;
}

interface ChatPanelProps {
  embedded?: boolean;
}

export default function ChatPanel({ embedded = false }: ChatPanelProps) {
  const [messages, setMessages] = useState<DisplayMessage[]>([]);
  const [input, setInput] = useState("");
  const [loading, setLoading] = useState(false);
  const [history, setHistory] = useState<ChatMessage[]>([]);
  const [conversations, setConversations] = useState<Conversation[]>([]);
  const [activeConvId, setActiveConvId] = useState<string | null>(null);
  const [convLoading, setConvLoading] = useState(false);
  const [toolSteps, setToolSteps] = useState<ToolCallStep[]>([]);
  const [aiUnavailable, setAiUnavailable] = useState(false);
  const listRef = useRef<HTMLDivElement>(null);
  const abortRef = useRef<AbortController | null>(null);
  const streamFailedRef = useRef(false);

  // 加载对话列表
  const loadConversations = useCallback(async () => {
    try {
      const list = await fetchConversations();
      setConversations(list);
    } catch {
      // silent
    }
  }, []);

  useEffect(() => {
    loadConversations();
  }, [loadConversations]);

  // 切换对话 → 加载历史
  const switchConversation = useCallback(async (convId: string) => {
    setActiveConvId(convId);
    setConvLoading(true);
    try {
      const msgs = await fetchMessages(convId);
      const filtered = msgs.filter((m) => m.role !== "tool" && !(m.role === "assistant" && !m.content));
      const display: DisplayMessage[] = filtered.map((m) => ({
        role: m.role as DisplayMessage["role"],
        content: m.content,
        name: m.name || undefined,
      }));
      setMessages(display);
      const steps = await fetchToolCalls(convId).catch(() => []);
      setToolSteps(steps.map((s) => ({ ...s })));
      // 构建 history（最近10轮）
      const chatMsgs: ChatMessage[] = [];
      for (const m of filtered) {
        chatMsgs.push({ role: m.role as ChatMessage["role"], content: m.content });
      }
      setHistory(chatMsgs.slice(-20)); // 保留最近10轮（20条）
    } catch {
      message.error("加载对话失败");
    } finally {
      setConvLoading(false);
    }
  }, []);

  // 新建对话
  const handleNewConv = useCallback(async () => {
    try {
      const conv = await createConversation();
      setConversations((prev) => [conv, ...prev]);
      setActiveConvId(conv.id);
      setMessages([]);
      setHistory([]);
      setToolSteps([]);
    } catch {
      message.error("创建对话失败");
    }
  }, []);

  // 删除对话
  const handleDeleteConv = useCallback(async (convId: string) => {
    try {
      await deleteConversation(convId);
      setConversations((prev) => prev.filter((c) => c.id !== convId));
      if (activeConvId === convId) {
        setActiveConvId(null);
        setMessages([]);
        setHistory([]);
        setToolSteps([]);
      }
    } catch {
      message.error("删除对话失败");
    }
  }, [activeConvId]);

  useEffect(() => {
    listRef.current?.scrollTo({ top: listRef.current.scrollHeight, behavior: "smooth" });
  }, [messages]);

  /** 发送失败统一落点：AI 未配置 → 引导文案 + 提示条；其余 → 可见通用错误（不再兜底为"（无回复）"） */
  const applyAssistantError = useCallback((err: string) => {
    setLoading(false);
    streamFailedRef.current = true;
    const disp = aiErrorDisplay(err, "请求失败，请稍后重试");
    if (disp.notConfigured) setAiUnavailable(true);
    setMessages((prev) => {
      const next = [...prev];
      const last = next[next.length - 1];
      if (last && last.role === "assistant") {
        last.content = disp.notConfigured ? disp.text : `❌ ${disp.text}`;
        last.loading = false;
      }
      return next;
    });
  }, []);

  const handleSend = () => {
    const text = input.trim();
    if (!text || loading) return;
    setInput("");
    setAiUnavailable(false);
    streamFailedRef.current = false;

    const userMsg: DisplayMessage = { role: "user", content: text };
    const assistantMsg: DisplayMessage = { role: "assistant", content: "", loading: true };
    setMessages((prev) => [...prev, userMsg, assistantMsg]);
    setLoading(true);

    let contentBuf = "";
    let isHtml = false;

    const controller = sendChatMessage(
      text,
      history,
      activeConvId,
      (event: ChatSSEEvent) => {
        switch (event.type) {
          case "progress":
            contentBuf += `${event.message}\n`;
            break;
          case "chunk":
            if (event.html) {
              isHtml = true;
              contentBuf = event.content || "";
            } else {
              contentBuf += event.content || "";
            }
            break;
          case "error": {
            streamFailedRef.current = true;
            const disp = aiErrorDisplay(event.message, "请求失败，请稍后重试");
            if (disp.notConfigured) {
              setAiUnavailable(true);
              contentBuf = disp.text;
            } else {
              contentBuf += `\n❌ ${disp.text}`;
            }
            break;
          }
          case "tool_step":
            setToolSteps((prev) => [
              ...prev,
              {
                id: `${Date.now()}-${event.name}`,
                round_no: 1,
                fn_name: event.name || "",
                status: event.status === "error" ? "error" : "success",
                duration_ms: event.duration_ms ?? null,
                created_at: new Date().toISOString(),
              },
            ]);
            break;
        }
        setMessages((prev) => {
          const next = [...prev];
          const last = next[next.length - 1];
          if (last && last.role === "assistant") {
            last.content = contentBuf;
            last.html = isHtml;
            last.loading = false;
          }
          return [...next];
        });
      },
      (err) => applyAssistantError(err),
      (convId) => {
        setLoading(false);
        const finalContent = contentBuf || (streamFailedRef.current ? "AI 回复失败，请稍后重试" : "（无回复）");
        setHistory((prev) => [
          ...prev,
          { role: "user", content: text },
          { role: "assistant", content: finalContent },
        ]);
        setMessages((prev) => {
          const next = [...prev];
          const last = next[next.length - 1];
          if (last && last.role === "assistant") {
            last.content = finalContent;
            last.html = isHtml;
            last.loading = false;
          }
          return next;
        });
        // 如果是新对话，刷新列表（标题已更新）
        if (!activeConvId && convId) {
          setActiveConvId(convId);
          loadConversations();
        }
      }
    );
    abortRef.current = controller;
  };

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === "Enter" && !e.shiftKey) {
      e.preventDefault();
      handleSend();
    }
  };

  const handleStop = () => {
    abortRef.current?.abort();
    setLoading(false);
  };

  // ─── 内嵌模式（浮动按钮 Drawer）：不显示对话列表 ───
  // ─── 内嵌模式（浮动按钮 Drawer）───
  if (embedded) {
    return (
      <div style={{ height: "100%", display: "flex", flexDirection: "column" }}>
        {aiUnavailable && <AiNotConfiguredHint onClose={() => setAiUnavailable(false)} />}
        {/* 对话选择 + 新建 */}
        <div style={{ display: "flex", gap: 6, marginBottom: 8, alignItems: "center" }}>
          <div
            style={{
              flex: 1,
              display: "flex",
              gap: 4,
              overflowX: "auto",
              paddingBottom: 2,
              scrollbarWidth: "none",
            } as React.CSSProperties}
          >
            {conversations.map((c) => (
              <div
                key={c.id}
                style={{
                  display: "flex",
                  alignItems: "center",
                  gap: 2,
                  padding: "3px 4px 3px 10px",
                  borderRadius: 12,
                  fontSize: 12,
                  cursor: "pointer",
                  whiteSpace: "nowrap",
                  flexShrink: 0,
                  maxWidth: 150,
                  background: activeConvId === c.id ? "#1677ff" : "#f0f0f0",
                  color: activeConvId === c.id ? "#fff" : "#666",
                  fontWeight: activeConvId === c.id ? 500 : 400,
                  transition: "all 0.2s",
                }}
              >
                <span
                  onClick={() => switchConversation(c.id)}
                  style={{ overflow: "hidden", textOverflow: "ellipsis" }}
                >
                  {c.title}
                </span>
                <Popconfirm
                  title="删除？"
                  onConfirm={(e) => { e?.stopPropagation(); handleDeleteConv(c.id); }}
                  onCancel={(e) => e?.stopPropagation()}
                  okText="删"
                  cancelText="否"
                  placement="bottom"
                >
                  <CloseOutlined
                    onClick={(e) => e.stopPropagation()}
                    style={{
                      fontSize: 12,
                      padding: 2,
                      borderRadius: "50%",
                      color: activeConvId === c.id ? "rgba(255,255,255,0.7)" : "#999",
                      flexShrink: 0,
                    }}
                  />
                </Popconfirm>
              </div>
            ))}
          </div>
          <Button size="small" icon={<PlusOutlined />} onClick={handleNewConv} disabled={loading} style={{ flexShrink: 0 }} />
        </div>
        <div
          ref={listRef}
          style={{
            flex: 1,
            overflow: "auto",
            marginBottom: 8,
            background: "#fff",
            borderRadius: 8,
            padding: 8,
          }}
        >
          {convLoading ? (
            <div style={{ textAlign: "center", paddingTop: 40 }}><Spin size="small" /></div>
          ) : messages.length === 0 ? (
            <div style={{ textAlign: "center", color: "#999", paddingTop: 40 }}>
              <AppIcon name="ai" size={36} style={{ marginBottom: 12 }} />
              <Paragraph type="secondary" style={{ fontSize: 12 }}>
                你好！可以问我系统里的数据：
              </Paragraph>
              <Paragraph type="secondary" style={{ fontSize: 12 }}>
                "查看仪表盘" · "列出企业" · "生成系统概览报告"
              </Paragraph>
            </div>
          ) : (
            messages.map((msg, i) => (
              <div
                key={i}
                style={{
                  marginBottom: 8,
                  display: "flex",
                  justifyContent: msg.role === "user" ? "flex-end" : "flex-start",
                }}
              >
                <div
                  style={{
                    maxWidth: msg.role === "user" ? "75%" : "95%",
                    padding: msg.role === "user" ? "8px 14px" : "12px 16px",
                    borderRadius: 12,
                    background: msg.role === "user" ? "#1677ff" : "#fff",
                    color: msg.role === "user" ? "#fff" : "#333",
                    border: msg.role === "assistant" ? "1px solid #e8e8e8" : "none",
                    fontSize: 13,
                    overflow: "hidden",
                  }}
                >
                  {msg.role === "assistant" && toolSteps.length > 0 && (
                    <div style={{ display: "flex", flexWrap: "wrap", gap: 4, marginBottom: 6 }}>
                      {toolSteps.map((s) => (
                        <span
                          key={s.id}
                          style={{
                            fontSize: 12,
                            padding: "1px 8px",
                            borderRadius: 10,
                            background: s.status === "error" ? "#fff2f0" : "#f6ffed",
                            color: s.status === "error" ? "#cf1322" : "#389e0d",
                          }}
                        >
                          {s.status === "error" ? "✗" : "✓"} {s.fn_name} {s.duration_ms != null ? `${s.duration_ms}ms` : ""}
                        </span>
                      ))}
                    </div>
                  )}
                  {msg.loading ? (
                    <Spin size="small" />
                  ) : msg.role === "user" ? (
                    <div style={{ whiteSpace: "pre-wrap", wordBreak: "break-word" }}>{msg.content}</div>
                  ) : msg.html ? (
                    <div dangerouslySetInnerHTML={{ __html: DOMPurify.sanitize(msg.content || "") }} />
                  ) : (
                    <div dangerouslySetInnerHTML={{ __html: DOMPurify.sanitize(md.render(msg.content || "")) }} />
                  )}
                </div>
              </div>
            ))
          )}
        </div>
        <div style={{ display: "flex", gap: 8 }}>
          <Input.TextArea
            value={input}
            onChange={(e) => setInput(e.target.value)}
            onKeyDown={handleKeyDown}
            placeholder="输入消息..."
            autoSize={{ minRows: 1, maxRows: 3 }}
            disabled={loading}
            style={{ flex: 1, fontSize: 13 }}
          />
          {loading ? (
            <Button danger size="small" onClick={handleStop}>停止</Button>
          ) : (
            <Button type="primary" size="small" icon={<SendOutlined />} onClick={handleSend} disabled={!input.trim()} />
          )}
        </div>
      </div>
    );
  }
  // ─── 全屏模式（/chat 路由）：对话列表 + 消息区 ───
  return (
    <div style={{ display: "flex", height: "calc(100vh - 200px)", gap: 0 }}>
      {/* 对话列表侧边 */}
      <div
        style={{
          width: 220,
          borderRight: "1px solid #f0f0f0",
          display: "flex",
          flexDirection: "column",
          background: "#fafafa",
        }}
      >
        <div style={{ padding: "12px 12px 8px", borderBottom: "1px solid #f0f0f0" }}>
          <Button type="primary" block icon={<PlusOutlined />} onClick={handleNewConv}>
            新建对话
          </Button>
