                  style={{
                    marginBottom: 10,
                    display: "flex",
                    justifyContent: msg.role === "user" ? "flex-end" : "flex-start",
                  }}
                >
                  <div
                    style={{
                      maxWidth: msg.role === "user" ? "60%" : "85%",
                      padding: msg.role === "user" ? "8px 14px" : "12px 16px",
                      borderRadius: 12,
                      background: msg.role === "user" ? "#1677ff" : "#f5f5f5",
                      color: msg.role === "user" ? "#fff" : "#333",
                      fontSize: 14,
                      overflow: "hidden",
                    }}
                  >
                    {msg.role === "assistant" && toolSteps.length > 0 && (
                      <div style={{ display: "flex", flexWrap: "wrap", gap: 4, marginBottom: 6 }}>
                        {toolSteps.map((s) => (
                          <span
                            key={s.id}
                            style={{
                              fontSize: 12,
                              padding: "1px 8px",
                              borderRadius: 10,
                              background: s.status === "error" ? "#fff2f0" : "#f6ffed",
                              color: s.status === "error" ? "#cf1322" : "#389e0d",
                            }}
                          >
                            {s.status === "error" ? "✗" : "✓"} {s.fn_name} {s.duration_ms != null ? `${s.duration_ms}ms` : ""}
                          </span>
                        ))}
                      </div>
                    )}
                    {msg.loading ? (
                      <Spin size="small" />
                    ) : msg.role === "user" ? (
                      <div style={{ whiteSpace: "pre-wrap", wordBreak: "break-word" }}>{msg.content}</div>
                    ) : msg.html ? (
                      <div dangerouslySetInnerHTML={{ __html: DOMPurify.sanitize(msg.content || "") }} />
                    ) : (
                      <div dangerouslySetInnerHTML={{ __html: DOMPurify.sanitize(md.render(msg.content || "")) }} />
                    )}
                  </div>
                </div>
              ))}
            </div>
            <div style={{ display: "flex", gap: 8, paddingBottom: 8 }}>
              <Input.TextArea
                value={input}
                onChange={(e) => setInput(e.target.value)}
                onKeyDown={handleKeyDown}
                placeholder="输入消息... Enter 发送，Shift+Enter 换行"
                autoSize={{ minRows: 1, maxRows: 4 }}
                disabled={loading}
                style={{ flex: 1, fontSize: 14 }}
              />
              {loading ? (
                <Button danger onClick={handleStop}>停止</Button>
              ) : (
                <Button type="primary" icon={<SendOutlined />} onClick={handleSend} disabled={!input.trim()}>发送</Button>
              )}
            </div>
          </>
        )}
      </div>
    </div>
  );
}

